/// <summary>
/// 
/// </summary>
/// <param name="sender"></param>
/// <param name="e"></param>
[FormControlEventHandler(formControlStr(SalesTable, METRunMetCashCreditCheck), FormControlEventType::Modified)]
public static void METCreditCheck_OnClicked(FormControl sender, FormControlEventArgs e)
{       
    FormDataSource SalesTable_ds = sender.formRun().dataSource(formDataSourceStr(SalesTable, SalesTable));
    SalesTable salesTable = SalesTable_ds.cursor();

    if (Box::okCancel("Are you sure you want to send sales order for credit management?", DialogButton::Cancel) == DialogButton::Ok)
    {
        FormletterJournalCreate::deletePreviousCreditHoldList(SalesTable);
        FormletterJournalCreate::SOProformaPosting(salesTable);
        // this.triggerCreditManagement(salesTable);

        Info("Sales order sent to credit management.");
    }
}

public static void SOProformaPosting(SalesTable salesTable)
{

    SalesFormLetter salesFormLetter;
   // salesTable salesTable;
    //salesTable = SalesTable::find('SO-123');
    salesFormLetter = SalesFormLetter::construct(
        DocumentStatus::Confirmation);

        salesFormLetter.update(
        salesTable,
        systemDateGet(),
        SalesUpdate::All,
        AccountOrder::None,
        NoYes::Yes,
        NoYes::No,
        NoYes::No
        );

    infolog.cut();

}

public static void deletePreviousCreditHoldList(SalesTable _salesTable)
{
    CredManTable credManTableDel;
    CredManTrans credManTrans;
    SalesLine    salesLine;
    ttsbegin;
    _salesTable.selectForUpdate(true);
    _salesTable.CredManId = '';
    _salesTable.update();
    ttscommit;
    ttsbegin;
    select forupdate credManTableDel
        where credManTableDel.SalesId == _salesTable.SalesId;

    credManTableDel.delete();
    ttscommit;



    ttsbegin;
    while select forupdate credManTrans
        join salesLine
        where credManTrans.InventTransId == salesLine.InventTransId
        && salesLine.SalesId == _salesTable.SalesId
    {
        credManTrans.delete();
    }
    ttscommit;

    // Remove credmadtable
    /// Update so
    // Update credtrans

}
